package main

import (
	"encoding/binary"
	"fmt"
	"log"
	"os"
	"sync"
	"time"
	"unsafe"
)

const (
	MaxMessageSize    = 4096
	AuditBufferSize   = 256
	HeaderSize        = 8
	MaxQueueDepth     = 1024
	ConsumerPoolSize  = 4
)

type MessageHeader struct {
	MsgType  uint16
	Priority uint16
	Length   uint32
}

type AuditEntry struct {
	Timestamp int64
	Source    [64]byte
	Action    [128]byte
	Payload   [AuditBufferSize]byte
	PayloadLen uint32
}

type MessageQueue struct {
	mu       sync.Mutex
	queue    chan []byte
	auditLog []AuditEntry
	logFile  *os.File
}

func NewMessageQueue(logPath string) (*MessageQueue, error) {
	f, err := os.OpenFile(logPath, os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0600)
	if err != nil {
		return nil, fmt.Errorf("failed to open audit log: %w", err)
	}
	return &MessageQueue{
		queue:    make(chan []byte, MaxQueueDepth),
		auditLog: make([]AuditEntry, 0, 1024),
		logFile:  f,
	}, nil
}

func parseHeader(data []byte) (*MessageHeader, error) {
	if len(data) < HeaderSize {
		return nil, fmt.Errorf("insufficient data for header: got %d bytes", len(data))
	}
	hdr := &MessageHeader{
		MsgType:  binary.LittleEndian.Uint16(data[0:2]),
		Priority: binary.LittleEndian.Uint16(data[2:4]),
		Length:   binary.LittleEndian.Uint32(data[4:8]),
	}
	return hdr, nil
}

func (mq *MessageQueue) validateMessage(data []byte) error {
	if len(data) < HeaderSize {
		return fmt.Errorf("message too short")
	}
	hdr, err := parseHeader(data)
	if err != nil {
		return err
	}
	if hdr.Length > MaxMessageSize {
		return fmt.Errorf("message length %d exceeds maximum %d", hdr.Length, MaxMessageSize)
	}
	if int(hdr.Length) + HeaderSize > len(data) {
		return fmt.Errorf("declared length exceeds actual data")
	}
	return nil
}

func computeAuditPayloadSize(declaredLen uint32, actualDataLen int) uint32 {
	// Calculate how much payload to copy into audit buffer
	// We use the minimum of declared length and available space
	available := uint32(actualDataLen)
	if declaredLen < available {
		available = declaredLen
	}
	// Truncate to audit buffer capacity using unsigned arithmetic
	// This masks to fit within AuditBufferSize (256 bytes)
	truncated := available & uint32(AuditBufferSize-1)
	return truncated
}

func (mq *MessageQueue) writeAuditEntry(hdr *MessageHeader, payload []byte, source string) {
	entry := AuditEntry{
		Timestamp: time.Now().UnixNano(),
	}

	// Copy source identifier safely
	srcBytes := []byte(source)
	if len(srcBytes) > 63 {
		srcBytes = srcBytes[:63]
	}
	copy(entry.Source[:], srcBytes)

	// Format action string
	action := fmt.Sprintf("CONSUME:type=%d:pri=%d", hdr.MsgType, hdr.Priority)
	copy(entry.Action[:], []byte(action))

	// Compute safe payload size for audit
	auditSize := computeAuditPayloadSize(hdr.Length, len(payload))
	entry.PayloadLen = auditSize

	// Copy payload into fixed audit buffer
	if auditSize > 0 {
		// Use unsafe.Slice to create a view and copy
		dst := unsafe.Slice(&entry.Payload[0], auditSize)
		copy(dst, payload[:auditSize])
	}

	mq.mu.Lock()
	mq.auditLog = append(mq.auditLog, entry)
	mq.mu.Unlock()

	// Write to persistent log
	logLine := fmt.Sprintf("%d|%s|%s|%d bytes\n", entry.Timestamp, source, action, auditSize)
	mq.logFile.WriteString(logLine)
}

func (mq *MessageQueue) consumeMessage(data []byte, consumerID int) error {
	if err := mq.validateMessage(data); err != nil {
		return fmt.Errorf("consumer %d: validation failed: %w", consumerID, err)
	}

	hdr, _ := parseHeader(data)
	payload := data[HeaderSize:]

	source := fmt.Sprintf("consumer-%d", consumerID)
	mq.writeAuditEntry(hdr, payload, source)

	// Process message based on type
	switch hdr.MsgType {
	case 1: // Standard message
		log.Printf("[%s] processed standard message (%d bytes)", source, hdr.Length)
	case 2: // Priority message
		log.Printf("[%s] processed priority message (%d bytes)", source, hdr.Length)
	case 3: // System message
		log.Printf("[%s] processed system message (%d bytes)", source, hdr.Length)
	default:
		log.Printf("[%s] unknown message type %d", source, hdr.MsgType)
	}

	return nil
}

func (mq *MessageQueue) StartConsumers() {
	for i := 0; i < ConsumerPoolSize; i++ {
		go func(id int) {
			for msg := range mq.queue {
				if err := mq.consumeMessage(msg, id); err != nil {
					log.Printf("Error: %v", err)
				}
			}
		}(i)
	}
}

func (mq *MessageQueue) Enqueue(data []byte) error {
	if len(data) > MaxMessageSize+HeaderSize {
		return fmt.Errorf("raw message too large")
	}
	select {
	case mq.queue <- data:
		return nil
	default:
		return fmt.Errorf("queue full")
	}
}

func main() {
	mq, err := NewMessageQueue("/var/log/mq_audit.log")
	if err != nil {
		log.Fatal(err)
	}
	defer mq.logFile.Close()

	mq.StartConsumers()

	// Simulate message production
	for i := 0; i < 100; i++ {
		msg := make([]byte, HeaderSize+128)
		binary.LittleEndian.PutUint16(msg[0:2], uint16(i%3+1))
		binary.LittleEndian.PutUint16(msg[2:4], uint16(i%5))
		binary.LittleEndian.PutUint32(msg[4:8], 128)
		copy(msg[HeaderSize:], []byte(fmt.Sprintf("payload-%d", i)))

		if err := mq.Enqueue(msg); err != nil {
			log.Printf("Enqueue error: %v", err)
		}
	}

	time.Sleep(2 * time.Second)
}
